    const c = cfgOf(cfg);
    if (!sched || !sched.s) return sched ? sched.lastReviewAt : 0;
    const factor = Math.log(c.targetR) / Math.log(0.9);
    return sched.lastReviewAt + sched.s * factor * DAY;
